head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.setBroadcast(false);
};
scwin.trigger2_onclick = function(e) {
    dataList1.setBroadcast(true);
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.setVal = function() {
    scwin.fireDbClick(WebSquare.wUnit.getObjById('wq_uuid_5_cell_0_0'));
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_5_cell_0_0').innerText == '333';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById($p.id + 'wq_uuid_5_cell_0_0').innerText == '333';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getObjById($p.id+"wq_uuid_9").getValue() == '33';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 그리드뷰의 첫번째 필드에 마우스를 클릭하고 우측하단의 inputbox에 값을 수정한다.
    //1. After executing the sample file, click mouse on the first field of the grid view and modify the value in the inputbox on the bottom right.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_wq_uuid_5__col1').setValue(333)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 그리드뷰의 첫번째 필드에 값이 수정된다.(이전버전에서는 수정되지 않음)
    //1. The value is modified in the first field of the grid view (not modified in previous versions).
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. broadcase fals버튼을 클릭하고 동일하게  inputbox에 값을 수정한다.
    //2. Click on the broadcase fals button and modify the value in the input box.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_9').setValue('33')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 그리드뷰의 첫번째 필드에 값이 수정되지 않는다.(정상임)
    //2. Values are not modified in the first field of the grid view (normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /*
    	Broadcast 사용시 selectbox를 사용할수 없음.(2016.03.16 요청)
    */
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
